// HasUmat applies the HasEdge predicate on the "umat" edge.
func HasUmat() predicate.UmatSakramen {
	return predicate.UmatSakramen(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UmatTable, UmatColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUmatWith applies the HasEdge predicate on the "umat" edge with a given conditions (other predicates).
func HasUmatWith(preds ...predicate.Umat) predicate.UmatSakramen {
	return predicate.UmatSakramen(func(s *sql.Selector) {
		step := newUmatStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UmatSakramen) predicate.UmatSakramen {
	return predicate.UmatSakramen(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UmatSakramen) predicate.UmatSakramen {
	return predicate.UmatSakramen(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UmatSakramen) predicate.UmatSakramen {
	return predicate.UmatSakramen(sql.NotPredicates(p))
}
